<?php
namespace App\Http\Requests\Api; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class ControllerRequest extends FormRequest {public function authorize():bool{return true;}public function rules():array{$id=$this->route('controller')?->id;return ['machine_id'=>'required|exists:machines,id','controller_code'=>['required','string','max:80',Rule::unique('tn_controllers')->ignore($id)],'name'=>'required|string|max:255','model_type'=>['required',Rule::in(['TNH','TNL','TNS'])],'slave_id'=>['required','integer','min:1','max:247',Rule::unique('tn_controllers')->ignore($id)],'communication'=>['required',Rule::in(['RS485'])],'baudrate'=>'required|integer','parity'=>['required',Rule::in(['N','E','O'])],'stopbits'=>'required|integer|between:1,2','polling_interval'=>'required|integer|min:100','firmware_version'=>'nullable|string|max:100','status'=>['required',Rule::in(['Active','Inactive'])],'control_model'=>['sometimes',Rule::in(['fixed','program'])]];}}
